constraints:
1 ≤ N ≤ 10^{5}
2^{0} ≤ A[i] < 2^{31}

expected time complexity: O(N * log_{2}(Max(A_{i})))
expected auxiliary space: O(1)

standard_solution_code:
MOD = 1000000007

class Solution:

	def countBits(self, N, A):
		MOD = 1000000007
		result = 0
		for i in range(32):
			count = 0
			for j in range(N):
				if A[j] & 1 << i:
					count += 1
			result += count * (N - count) * 2
		return result % MOD
